package android.database.sqlite;
import android.content.ContentValues;import android.database.Cursor;import java.util.*;
/** A deterministic transaction adapter, not Android SQLite. */
public class SQLiteDatabase{
 public static final int CONFLICT_REPLACE=5;public LinkedHashMap<Integer,Map<String,Object>> rows=new LinkedHashMap<>();public LinkedHashMap<String,String> settings=new LinkedHashMap<>();public boolean failDefaultWrite;public int begins,ends;public Runnable beforeUpdate,beforeBegin;
 final java.util.concurrent.locks.ReentrantLock lock=new java.util.concurrent.locks.ReentrantLock();final ArrayDeque<Boolean> success=new ArrayDeque<>();LinkedHashMap<Integer,Map<String,Object>> beforeRows;LinkedHashMap<String,String> beforeSettings;boolean childFailed;
 public void beginTransaction(){if(beforeBegin!=null)beforeBegin.run();lock.lock();begins++;if(success.isEmpty()){beforeRows=new LinkedHashMap<>();for(var e:rows.entrySet())beforeRows.put(e.getKey(),new LinkedHashMap<>(e.getValue()));beforeSettings=new LinkedHashMap<>(settings);childFailed=false;}success.push(false);}
 public void setTransactionSuccessful(){success.pop();success.push(true);}
 public void endTransaction(){boolean ok=success.pop();if(!ok)childFailed=true;if(success.isEmpty()&&childFailed){rows=beforeRows;settings=beforeSettings;}ends++;lock.unlock();}
 public int update(String table,ContentValues values,String where,String[] args){if(beforeUpdate!=null)beforeUpdate.run();int id=Integer.parseInt(args[0]);Map<String,Object> row=rows.get(id);if(row==null)return 0;row.putAll(values);return 1;}
 public long insertWithOnConflict(String table,String column,ContentValues values,int conflict){if(failDefaultWrite&&values.get("name").equals("defaultSlot"))return -1;settings.put((String)values.get("name"),(String)values.get("value"));return 1;}
 public Cursor query(String table,String[] columns,String where,String[] args,String group,String having,String order){List<Map<String,Object>> data=new ArrayList<>();if(table.equals("app_settings")){String value=settings.get(args[0]);if(value!=null)data.add(new LinkedHashMap<>(Map.of("value",value)));}else if(args!=null){Map<String,Object> row=rows.get(Integer.parseInt(args[0]));if(row!=null)data.add(row);}else data.addAll(rows.values());return new Rows(data);}
 static final class Rows implements Cursor{final List<Map<String,Object>> rows;final List<String> keys;int index=-1;Rows(List<Map<String,Object>> values){rows=values;keys=rows.isEmpty()?new ArrayList<>():new ArrayList<>(rows.get(0).keySet());}public boolean moveToFirst(){index=0;return !rows.isEmpty();}public boolean moveToNext(){return ++index<rows.size();}public int getColumnIndexOrThrow(String name){int at=keys.indexOf(name);if(at<0)throw new IllegalArgumentException(name);return at;}Object value(int n){return rows.get(index).get(keys.get(n));}public String getString(int n){Object x=value(n);return x==null?"":String.valueOf(x);}public int getInt(int n){Object x=value(n);return x instanceof Number?((Number)x).intValue():Integer.parseInt(String.valueOf(x));}public long getLong(int n){Object x=value(n);return x instanceof Number?((Number)x).longValue():Long.parseLong(String.valueOf(x));}public void close(){}}
}
